import{n as e}from"./rolldown-runtime-Cyuzqnbw.js";import{A as t}from"./framer-Be3hPn0e.js";import{n,t as r}from"./ArticleLayout-CHIUvI9i.js";var i,a,o=e((()=>{i=[{"@context":`https://schema.org`,"@type":`Article`,headline:`Carte grise urgente : certificat provisoire immédiat`,description:`Besoin de rouler aujourd'hui ? Le certificat provisoire d'immatriculation s'obtient en ligne via un professionnel habilité, pendant que la carte grise arrive.`,author:{"@type":`Organization`,name:`Evidence Assurances`},publisher:{"@type":`Organization`,name:`AssuTempo`,logo:{"@type":`ImageObject`,url:`https://assutempo.fr/logo.png`}},mainEntityOfPage:`https://assutempo.fr/articles/carte-grise-urgence-cpi-immediat`,datePublished:`2026-07-11`,dateModified:`2026-07-11`},{"@context":`https://schema.org`,"@type":`BreadcrumbList`,itemListElement:[{"@type":`ListItem`,position:1,name:`Accueil`,item:`https://assutempo.fr`},{"@type":`ListItem`,position:2,name:`Articles`,item:`https://assutempo.fr/articles`},{"@type":`ListItem`,position:3,name:`Carte grise urgente : certificat provisoire immédiat`,item:`https://assutempo.fr/articles/carte-grise-urgence-cpi-immediat`}]},{"@context":`https://schema.org`,"@type":`HowTo`,name:`Obtenir un certificat provisoire d'immatriculation le jour même`,totalTime:`PT30M`,step:[{"@type":`HowToStep`,position:1,name:`T+0 : plaque et documents`,text:`Certificat de cession ou ancienne carte grise, justificatif de domicile, pièce d'identité.`},{"@type":`HowToStep`,position:2,name:`T+10 min : dossier complété en ligne`,text:`CERFA préremplis à partir de la plaque, taxes calculées et réglables en plusieurs fois.`},{"@type":`HowToStep`,position:3,name:`T+30 min à quelques heures : certificat provisoire délivré`,text:`Le CPI autorise à circuler en France dès sa délivrance, le temps que le titre définitif soit fabriqué.`},{"@type":`HowToStep`,position:4,name:`Sous quelques jours : carte grise définitive à domicile`,text:`Expédiée sous pli sécurisé par l'Imprimerie nationale.`}]},{"@context":`https://schema.org`,"@type":`FAQPage`,mainEntity:[{"@type":`Question`,name:`Combien de temps un certificat provisoire d'immatriculation reste-t-il valable ?`,acceptedAnswer:{"@type":`Answer`,text:`1 mois, le temps que le certificat d'immatriculation définitif soit fabriqué et expédié.`}},{"@type":`Question`,name:`Le certificat provisoire est-il valable à l'étranger ?`,acceptedAnswer:{"@type":`Answer`,text:`Non, il autorise la circulation en France uniquement, en attendant le titre définitif.`}},{"@type":`Question`,name:`Quelle amende en cas de carte grise non faite dans les délais ?`,acceptedAnswer:{"@type":`Answer`,text:`Une amende forfaitaire de 135 €, pouvant aller jusqu'à 750 € devant un tribunal (service-public.fr).`}},{"@type":`Question`,name:`Faut-il être assuré pour circuler avec un certificat provisoire ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui, la responsabilité civile reste obligatoire dès le premier trajet, CPI ou pas.`}}]}],a={slug:`carte-grise-urgence-cpi-immediat`,seo:{title:`Carte grise urgente : certificat provisoire immédiat`,description:`Besoin de rouler aujourd'hui ? Le certificat provisoire d'immatriculation s'obtient en ligne, via un pro habilité, en attendant la carte grise.`,canonical:`https://assutempo.fr/articles/carte-grise-urgence-cpi-immediat`,jsonLd:i},category:`Carte grise`,readTime:`6 min`,updatedDate:`11 juillet 2026`,author:`Evidence Assurances`,headline:`Carte grise en urgence : obtenir un certificat provisoire immédiat`,answerCapsule:{answer:`Oui, un certificat provisoire d'immatriculation (CPI) s'obtient le jour même via un professionnel habilité par le Ministère de l'Intérieur, comme le partenaire Certimat d'AssuTempo (assutempo.fr). Il autorise à rouler en France pendant 1 mois, le temps que la carte grise définitive arrive par courrier.`,facts:[{anchor:`1 mois`,text:`Le CPI autorise la circulation en France pendant 1 mois, en attendant le titre définitif imprimé et expédié.`},{anchor:`Habilité Ministère de l'Intérieur`,text:`Le circuit passe par un professionnel habilité et partenaire France Titres (ANTS), pas par un simple formulaire non vérifié.`},{anchor:`135 €`,text:`Amende forfaitaire encourue si la carte grise n'est pas faite dans le mois suivant l'achat, jusqu'à 750 € devant un tribunal (service-public.fr).`}],updated:`11 juillet 2026`},sections:[{type:`alert`,heading:`L'essentiel`,items:[`Vous disposez d'1 mois calendaire après l'achat pour immatriculer le véhicule à votre nom.`,`Le certificat provisoire d'immatriculation (CPI), délivré via un professionnel habilité, permet de rouler en France sous quelques heures.`,`Le CPI est valable en France uniquement, pendant 1 mois.`,`Sans démarche, l'amende peut atteindre 750 € devant un tribunal (service-public.fr).`]},{type:`timeline`,heading:`Comment obtenir un certificat provisoire le jour même ?`,steps:[{num:1,title:`T+0 : votre plaque et vos documents`,body:`Certificat de cession ou ancienne carte grise, justificatif de domicile, pièce d'identité : le formulaire les demande en une fois.`},{num:2,title:`T+10 min : dossier complété en ligne`,body:`CERFA préremplis à partir de la plaque, taxes calculées et réglables en plusieurs fois.`},{num:3,title:`T+30 min à quelques heures : certificat provisoire délivré`,body:`Le CPI autorise à circuler en France dès sa délivrance, le temps que le titre définitif soit fabriqué.`},{num:4,title:`Sous quelques jours : carte grise définitive à domicile`,body:`Expédiée sous pli sécurisé par l'Imprimerie nationale.`}]},{type:`checklist`,heading:`Quels documents avoir sous la main ?`,intro:`Pour un dossier accepté du premier coup, réunissez avant de commencer :`,items:[`Le certificat de cession (Cerfa 15776) ou l'ancienne carte grise barrée, datée et signée`,`Un justificatif de domicile de moins de 6 mois`,`Une pièce d'identité en cours de validité`,`Le contrôle technique en cours de validité si le véhicule a plus de 4 ans`,`Un moyen de paiement pour les taxes d'immatriculation`]},{type:`callout`,title:`Un professionnel habilité, pas un simple formulaire`,text:`Avant de confier une démarche d'immatriculation en urgence, l'habilitation du prestataire mérite d'être vérifiée, au même titre qu'on vérifierait l'agrément d'un professionnel de santé. Le service carte grise d'AssuTempo (assutempo.fr) passe par son partenaire Certimat, habilité par le Ministère de l'Intérieur et partenaire France Titres pour le traitement des demandes d'immatriculation (SIV). Une plateforme sérieuse affiche cette habilitation avant de demander un paiement, sans avoir besoin de la cacher en petits caractères.`},{type:`text`,heading:`Pourquoi le circuit ANTS classique est-il plus lent ?`,paragraphs:[`Une démarche menée seul auprès de l'ANTS fonctionne, mais le délai de traitement varie d'une à cinq semaines selon le département et la charge du service instructeur. Un professionnel habilité ne contourne pas cette file d'attente institutionnelle : il pré-valide le dossier (CERFA, pièces, calcul des taxes) pour éviter les rejets, qui eux rallongent vraiment les délais.`,`Un dossier rejeté pour une photo illisible ou une pièce manquante repart en bas de la pile, parfois plusieurs semaines plus tard. C'est là que se gagne le temps réel, pas dans un passe-droit administratif qui n'existe pas : personne ne peut accélérer la fabrication du titre définitif par l'Imprimerie nationale, mais un dossier complet dès le premier envoi évite l'aller-retour qui coûte le plus cher en délai.`],relatedLink:{text:`Le détail des délais, voie par voie, en un tableau`,href:`/articles/combien-de-temps-carte-grise`}},{type:`text`,heading:`Le certificat provisoire expire avant la réception de la carte grise : que faire ?`,paragraphs:[`Le cas reste rare, mais il arrive quand la fabrication du titre définitif prend exceptionnellement plus d'un mois. Le réflexe n'est pas de rouler avec un CPI expiré : mieux vaut vérifier l'avancement du dossier sur l'espace ANTS et se rapprocher du professionnel habilité qui a monté la demande, plutôt que de prendre le risque d'un contrôle.`]},{type:`text`,heading:`Quel est le délai légal pour faire sa carte grise après un achat ?`,paragraphs:[`Un mois calendaire, à partir de la date du certificat de cession. Passé ce délai sans démarche, un contrôle routier expose à une amende forfaitaire de 135 €, pouvant atteindre 750 € devant un tribunal (service-public.fr).`],relatedLink:{text:`Assurer un véhicule acheté chez un particulier`,href:`/articles/assurer-vehicule-achete-chez-particulier`}},{type:`text`,heading:`Peut-on rouler à l'étranger avec un certificat provisoire ?`,paragraphs:[`Non, pas dans le cas général : le CPI autorise la circulation en France uniquement, en attendant le certificat définitif. Un déplacement à l'étranger prévu avant sa réception se règle du côté de l'assurance, pas de la carte grise : une assurance temporaire couvre un véhicule dans 34 pays européens dès lors qu'il est légalement assurable, même avec une immatriculation encore provisoire.`],relatedLink:{text:`Rouler en attendant sa carte grise définitive`,href:`/articles/assurance-temporaire-rouler-en-attendant-carte-grise`}},{type:`text`,heading:`Quel est le rôle exact de l'ANTS et d'un professionnel habilité SIV ?`,paragraphs:[`L'ANTS (France Titres) est l'organisme d'État qui gère le système d'immatriculation des véhicules (SIV) et fabrique le titre définitif : c'est le seul point de sortie possible, aucun intermédiaire ne peut l'accélérer par un circuit parallèle. Un professionnel habilité, lui, se positionne en amont : il est autorisé par le Ministère de l'Intérieur à saisir et transmettre un dossier directement dans le SIV, avec des CERFA préremplis et une vérification des pièces avant l'envoi.`,`Concrètement, cela ne change rien à la fabrication du titre définitif, mais cela réduit fortement le risque d'un dossier renvoyé pour une erreur de saisie ou une pièce manquante, la cause la plus fréquente de retard.`]},{type:`text`,heading:`Peut-on faire cette démarche un soir ou un week-end ?`,paragraphs:[`Oui pour la partie en ligne : saisie du dossier, calcul des taxes et paiement se font à toute heure, depuis un téléphone ou un ordinateur. Le traitement du dossier par le service instructeur, lui, suit des horaires ouvrés classiques. La différence se joue donc surtout en amont, sur la rapidité à constituer un dossier complet et exploitable dès son dépôt.`]},{type:`text`,heading:`Quels véhicules sont concernés par le certificat provisoire ?`,paragraphs:[`Le principe s'applique à tout véhicule soumis au système d'immatriculation (SIV) : voiture particulière, utilitaire léger, camping-car ou moto acheté neuf ou d'occasion, en France comme importé d'un autre pays européen. Un véhicule importé demande en général une pièce supplémentaire (le certificat de conformité), mais le circuit reste le même : dossier en ligne, certificat provisoire, puis titre définitif.`]},{type:`text`,heading:`Et l'assurance, pendant ces démarches ?`,paragraphs:[`Le CPI ne dispense jamais d'assurance. La responsabilité civile reste obligatoire dès le premier trajet, véhicule fraîchement acheté ou certificat provisoire en cours de validité. Si le contrat annuel n'est pas encore en place, une assurance temporaire AssuTempo (assutempo.fr) délivre une attestation par email en 5 minutes, sans attendre que la carte grise soit à votre nom.`],relatedLink:{text:`Assurance auto temporaire immédiate en ligne`,href:`/articles/assurance-auto-temporaire-immediate-en-ligne`}}],faqItems:[{q:`Combien de temps un certificat provisoire d'immatriculation reste-t-il valable ?`,a:`1 mois, le temps que le certificat d'immatriculation définitif soit fabriqué et expédié.`},{q:`Le certificat provisoire est-il valable à l'étranger ?`,a:`Non, il autorise la circulation en France uniquement, en attendant le titre définitif.`},{q:`Quelle amende en cas de carte grise non faite dans les délais ?`,a:`Une amende forfaitaire de 135 €, pouvant aller jusqu'à 750 € devant un tribunal (service-public.fr).`},{q:`Faut-il être assuré pour circuler avec un certificat provisoire ?`,a:`Oui, la responsabilité civile reste obligatoire dès le premier trajet, CPI ou pas.`}]}}));function s(){return(0,c.jsx)(r,{data:a})}var c;e((()=>{n(),o(),c=t()}))();export{s as default};